bug_report:
[12 Regression] Deprecation warning/unavailable error when overriding member of virtual base class
Repro:

struct B {
    virtual void f() = 0;
};
struct C : virtual B {
    [[deprecated("meow")]]
    void f() override {}
};

<source>:6:24: warning: 'virtual void C::f()' is deprecated: meow [-Wdeprecated-declarations]
    6 |     void f() override {}
      |                        ^
<source>:6:10: note: declared here
    6 |     void f() override {}
      |          ^

Likewise:

struct B {
    virtual void f() = 0;
};
struct C : virtual B {
    [[gnu::unavailable("meow")]]
    void f() override {}
};

<source>:6:24: error: 'virtual void C::f()' is unavailable: meow
    6 |     void f() override {}
      |                        ^
<source>:6:10: note: declared here
    6 |     void f() override {}
      |          ^


Making the base class non-virtual makes the warning/error go away.
